<script src="assets/js/mobile-menu.js?v=1792590783"></script><script defer src="assets/js/legacy-widgets.js?v=1792590783" type="text/plain"></script><script type="text/plain">
/* Guard for a network-timing race the preload above can't fully close:
   if Elementor's native init consumes its hooks before the deferred chunk
   registers the video-playlist handler (depends on real-world latency —
   seen on the VPS, never on localhost), the playlist tabs never activate
   and the player pane stays blank. The fix is SCOPED: re-trigger the ready
   hook for ONLY this widget. A full elementorFrontend.init() re-ran every
   handler and raced the hero background video's YouTube API (its retry
   chain restarted mid-flight → intermittent dead hero video) and double-
   appended nav carets. runReadyTrigger is Elementor's own per-element
   dispatch, so nothing else is touched; no-op when native init succeeded. */
window.addEventListener('load', function () {
    if (document.querySelector('.e-tab-content.e-active')) return;
    if (!window.jQuery || !window.elementorFrontend) return;
    var handler = elementorFrontend.elementsHandler;
    if (handler && typeof handler.runReadyTrigger === 'function') {
        jQuery('.elementor-widget-video-playlist').each(function () {
            handler.runReadyTrigger(jQuery(this));
        });
    }
});
</script>
<script async defer type="text/plain"></script><script type="text/plain">
/* Pages render several reCAPTCHA widgets (inline forms + footer); PHP only
   receives the LAST widget's g-recaptcha-response. On submit, copy the page's
   ticked token into THIS form's captcha_token relay field. */
document.addEventListener('submit', function (e) {
    var f = e.target;
    if (!f.querySelector || !f.querySelector('.g-recaptcha')) return;
    var tok = '';
    document.querySelectorAll('textarea[name="g-recaptcha-response"]').forEach(function (t) {
        if (!tok && t.value) tok = t.value;
    });
    var h = f.querySelector('input[name="captcha_token"]');
    if (h && tok) h.value = tok;
}, true);
</script>
<script type="text/plain">
(function () {
    /* The legacy WPForms JS binds submit handlers on .wpforms-form and AJAX-
       posts them to the legacy server's admin-ajax.php (CORS-blocked in dev,
       pointless in prod — our PHP handlers own these forms). Its listeners are
       re-bound and partly native, so unbinding is unreliable: clone-replace
       each form node instead — cloning drops every listener (jQuery + native)
       while preserving the current field values. */
    function unhijack() {
        document.querySelectorAll('form.wpforms-form').forEach(function (f) {
            if (f.dataset.unhijacked) return;
            f.dataset.unhijacked = '1';
            f.querySelectorAll('input, textarea').forEach(function (i) {
                if (i.type === 'checkbox' || i.type === 'radio') {
                    if (i.checked) i.setAttribute('checked', 'checked'); else i.removeAttribute('checked');
                } else if (i.name !== 'csrf_token') {
                    i.setAttribute('value', i.value);
                }
            });
            f.querySelectorAll('textarea').forEach(function (t) {
                t.textContent = t.value;
            });
            var clone = f.cloneNode(true);
            f.parentNode.replaceChild(clone, f);
        });
    }
    document.addEventListener('DOMContentLoaded', unhijack);
    window.addEventListener('load', unhijack);
    setTimeout(unhijack, 1200);
})();
</script>
